import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"離為火","description":"周易折中 - 離為火","frontmatter":{"title":"離為火","description":"周易折中 - 離為火"},"headers":[],"relativePath":"classics/zhezhong/036.md","filePath":"classics/zhezhong/036.md"}'),h={name:"classics/zhezhong/036.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="離為火" tabindex="-1">離為火 <a class="header-anchor" href="#離為火" aria-label="Permalink to “離為火”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>離序卦：坎者，陷也。陷必有所麗，故受之以離。離者，麗也。陷於險難之中，則必有所附麗，理自然也。離所以次坎也。離，麗也，明也。取其陰麗於上下之陽，則為附麗之義；取其中虛，則為明義。離為火，火體虛麗於物而明者也；又為日，亦以虛明之象。</p><p>離：利貞，亨；畜牝牛，吉。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>離，麗也。陰麗於陽，其象為火，體陰而用陽也。物之所麗，貴乎得正。牝牛柔順之物也，故佔者能正則亨，而畜牝牛則吉也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>離，麗也。萬物莫不皆有所麗，有形則有麗矣。在人則為所親附之人，所由之道，所主之事，皆其所麗也。人之所麗，利於貞正。得其正，則可以亨通。故曰“離利貞亨”。畜牝牛吉，牛之性順而又牝焉，順之至也。既附麗於正，必能順於正道。如牝牛則吉也。畜牝牛，謂養其順德。人之順德，由養以成。既麗於正，當養習以成其順德也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：離之為卦，以柔為正，故必貞而後乃亨。柔處於內而履正中，牝之善也。外強而內順，牛之善也。離之為體，以柔順為主者也，故不可以畜剛猛之物，而吉於畜牝牛也。</p></li><li><p>郭氏忠孝曰 ：幹為馬，坤為牝馬。坤為牛，離為牝牛，象之宜也。</p></li><li><p>朱子語類 ：問：離卦是陽包陰，佔利畜牝牛，便也是宜畜柔順之物。曰：然。</p></li><li><p>呉氏澄曰 ：牛、牝皆坤象，離中畫一陰，坤之中畫也，故象牝牛。</p></li><li><p>胡氏炳文曰 ：坎之明在內，以剛健而行之於外；離之明在外，當柔順以養之於中。</p></li><li><p>呉氏曰慎曰 ：坎性就下，下不已則入坎窞；離性炎上，炎之盛則突如焚如。坎陷欲之類也，離炎忿之類也。坎維心亨以剛中，則不陷；離畜牝牛，以中順則不突。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>畜牝牛，胡氏、呉氏之說為切。蓋離明也，高明柔克，則用明而不傷。</p><p>象曰：明兩作，離大人以繼明照於四方</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>作起也</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>若雲兩明，則是二明，不見繼明之義。故云明兩，明而重兩，謂相繼也。作離，明兩而為離，繼明之義也。震巽之類，亦取洊隨之義，然離之義尤重也。大人以徳言，則聖人以位言，則王者。大人觀離明相繼之象，以世繼其明徳，照臨於四方。大凡以明相繼，皆繼明也。舉其大者，故以世襲繼照言之。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰：繼，謂不絕也。明照相繼，不絕曠也。</p></li><li><p>孔氏穎逹曰：繼續其明，乃照於四方。若明不繼續，則不得久為照臨。</p></li><li><p>朱子語類雲：明兩作，猶言水洊至今日明，來日又明。明字便是指日而言，只是一個明兩番作。</p></li><li><p>徐氏在漢曰：繼明者，無時不明也。照於四方者，無處不照也。惟其無時不明，所以無處不照，是之謂明明德於天下也。</p></li></ul><p>《彖》曰：離，麗也；日月麗乎天，百穀草木麗乎土；重明以麗乎正，乃化成天下</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>離麗也，謂附麗也。如日月則麗於天，百穀草木則麗於土。萬物莫不各有所麗，天地之中無無麗之物。在人當審其所麗，麗麗得其正則能亨也。重明以麗乎正，以卦才言也。上下皆離，重明也。五二皆處中正，麗乎正也。君臣上下皆有明德而處中正，可以化天下成文明之俗也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰：日月麗乎天而成明，百穀草木麗乎土而成文，故離為文又為明。</p></li><li><p>齊氏夢龍曰：龜山楊氏雲，火無常形，麗物而有形，最得本旨。人之生也，得水為精，得火為神。其合也，氣聚而形成於有其分也；氣散而神泯於無。蓋精所以為形，而神麗於形者也。天地形之大者也，日月麗天，百穀草木麗土，其神之發見而可見者也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>項氏、齊氏說則是陽麗乎陰而以為陰麗乎陽者非矣。惟張子正蒙之說得之。</p><p>柔麗乎中正，故亨；是以畜牝牛吉也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>二五以柔順麗於中正，所以能亨。人能養其至順以麗中正，則吉。故曰畜牝牛吉也。或曰：“二則中正矣，五以陰居陽得為正乎？”曰：“離主於所麗，五中正之位，六麗於正位，乃為正也。”學者知時義而不失輕重，則可以言易矣。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰：“重明以麗乎正”此統論一卦之義以釋卦名也，“柔麗乎中正”此以二五成卦之爻釋卦辭也。</p></li><li><p>胡氏炳文曰：坎之剛中，九五分數多，故九五曰“坎不盈”，卦辭釋有孚亦曰“水流而不盈”。離之中正，六二分數多，故卦辭曰“畜牝牛吉”，而六二爻辭亦曰“黃離元吉”。</p></li></ul><p>初九：履錯然，敬之無咎</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>以剛居下而處明體，志欲上進，故有履錯然之象。敬之則無咎矣，戒佔者宜如是也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>陽固好動，又居下而離體。陽居下則欲進，離性炎上，志在上麗，幾於躁動。其履錯然，謂交錯也。雖未進而跡已動矣，動則失居下之分而有咎也。然其剛明之才，若知其義而敬慎之，則不至於咎矣。初在下無位者也，明其身之進退乃所麗之道也。其志既動，不能敬慎，則妄動，是不明所麗，乃有咎也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：身處離初，故其所履踐恆錯然。敬慎不敢自寧，故云“履錯然敬之無咎”。若能如此恭敬，則得避其禍而無咎。</p></li><li><p>王氏昭素曰 ：處萬物相見之初，履錯雜之時。</p></li><li><p>胡氏瑗曰 ：錯然者，敬之之貌也。居離之初，如日之初生，於事之初，則當常錯然警懼以進德修業，所以得免其咎。</p></li><li><p>馮氏當可曰 ：日方出人夙興之晨也，履錯然動之始也。於其始而加敬，則終必吉。禍福幾微，每萌於初動之時，故戒其初。</p></li><li><p>趙氏彥肅曰 ：能敬則動與物交皆天理也，不能敬則役於物而生咎矣。日出而作，故發此象。</p></li><li><p>胡氏一桂曰 ：錯然是事物紛錯之意，能敬則心有主宰，酬應不亂，可免於咎；不能敬則反是。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>履錯然，王氏、馮氏、胡氏之說為是。蓋錯雜者，處應物之初也；敬者，養明德之本也。人心之德，敬則明，不敬則昏。於應物之初而知敬，其即於咎者鮮矣。</p><p>象曰：履錯之敬以闢咎也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>履錯然欲動而知敬愼，不敢進，所以求闢免過咎也。居明而剛，故知而能闢，不剛明則妄動矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><p>徐氏在漢曰：敬以直內，坤之徳也。履錯之敬，是體坤之徳，所謂畜牝牛吉者也。咎不期遠而自遠，故曰以闢咎也。</p><p>六二：黃離，元吉</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>黃中色柔，離乎中而得其正，故其象佔如此。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二居中得正，麗於中正也。黃中之色，文之美也。文明中正，美之盛也。故云“黃離”，以文明中正之德，上同於文明中順之君，其明如是，所麗如是，大善之吉也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：居中得位，以柔處柔，履文明之盛而得其中，故曰“黃離元吉”也。</p></li><li><p>劉氏牧曰 ：離為火之象，焰猛而易燼（如九四所示）。過盛則有衰竭之兇（如九三所示）。惟二得中，離之元吉也。</p></li><li><p>郭氏雍曰 ：離之六爻，二五為美。五得中而非正，柔麗中正者，惟六二盡之。黃為中之色，而德之至美者也。故言元吉，其義與坤六五相類。</p></li><li><p>俞氏琰曰 ：九三言“日昃之離”，六二其“日中之離”乎？居下卦之中而得其中道，故比他爻為最吉。六二蓋離之主爻也。</p></li><li><p>楊氏啟新曰 ：畜牝牛而利貞，六二得之，明而不失其中正，故曰“黃離”。</p></li></ul><p>象曰：黃離元吉，得中道也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>所以元吉者，以其得中道也。不雲正者，離以中為重，所以成文明由中也。正在其中矣。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><p>郭氏忠孝曰：離之所以亨，柔麗乎中正，故亨也。黃離之所以元吉，文明而用中，故元吉也。故盡一卦之美，其惟六二乎。</p><p>九三：日昃之離，不鼓缶而歌，則大耋之嗟，兇。</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>重離之間，前明將盡，故有日昃之象。不安常以自樂，則不能自處而兇矣。戒佔者宜如是也。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>八純卦皆有二體之義。離卦，內外皆明。九三居下體之終，是前明將盡，後明當繼之時。人之始終，時之革易也，故為日昃之離。日下昃之明也，昃則將沒矣。以理言之，盛必有衰，始必有終，常道也。達者順理為樂，缶常用之器也，鼓缶而歌，樂其常也。不能如是，則以大耋為嗟，憂乃為兇也。大耋，傾沒也，人之終盡。達者則知其常理，樂天而已，遇常皆樂，如鼓缶而歌。不達者則恐怛有將盡之悲，乃大耋之嗟，為其兇也。此處死生之道也。耋與昳同。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>苟氏爽曰：初為日出，二為日中，三為日昃。</p></li><li><p>梁氏寅曰：三居下離之終，乃日昃之時也。夫持滿定傾，非中正之君子不能。三處日之夕，而過剛不中，其志荒矣。故不鼓缶而歌，則大耋之嗟。其歌也，樂之失常也；其嗟也，哀之失常也。哀樂失常，能無兇乎？君子值此之時，則思患之心與樂天之誠並行而不悖，是固不暇於歌矣，而亦何至於嗟乎？</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>梁氏之說獨得爻義。蓋日昃者，喻心之昏，非喻境之變也。</p><p>象曰：日昃之離，何可久也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>日既傾昃，明能久乎？明者知其然也，故求人以繼其事，退處以休其身。安常處順，何足以為兇也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>日昃喻心德之昏也。心德明則常繼，昏則不能以久。</p><p>九四：突如其來，如焚如死，如棄如。</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>後明將繼之時，而九四以剛迫之，故其象如此。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>九四離下體而升上體，繼明之初，故言繼承之義。在上而近君，繼承之地也。以陽居離體而處四，剛躁而不中正，且重剛以不正而剛盛之，突如而來，非善繼者也。夫善繼者，必有巽讓之誠、順承之道，若舜啟然。今四突如其來，失善繼之道也。又承六五陰柔之君，其剛盛陵爍之氣焰如焚然，故曰焚如。四之所行不善如此，必被禍害，故曰死如。失繼紹之義，承上之道皆逆德也，眾所棄絕，故云棄如。至於死棄，禍之極矣，故不假言兇也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>章氏潢曰：明之於人，猶火之於木。火宿於木而能焚木，明本於人而能害人。顧用之何如耳。九四不中不正，剛氣燥暴，其害若此。</p></li><li><p>何氏楷曰：三處下卦之盡，似日之過中；四處上卦之始，似火之驟烈。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>離，明德也。繼明者，所謂有緝熙於光明，其明不息也。與繼世之義全無交涉。因先儒有以明兩為繼世者，故程傳用說九四爻義於經意似遠。章氏、何氏謂燥暴驟烈者得之，不能以順德養其明，過也。</p><p>象曰：突如其來，如無所容也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>無所容，言焚死棄也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>上陵其君，不順所承，人惡眾棄，天下所不容也。案突如其來，如書所謂昏暴者是也，非人不容之，自若無所容爾。</p><p>六五：出涕沱若，戚嗟若，吉。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陰居尊，柔麗乎中，然不得其正而迫於上下之陽，故憂懼如此，然後得吉。戒佔者宜如是也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五居尊位而守中，有文明之德，可謂善矣。然以柔居上，在下無助，獨附麗於剛強之間，危懼之也。唯其明也，故能畏懼之深，至於出涕；憂慮之深，至於戚嗟，所以能保其吉也。出涕戚嗟，極言其憂懼之深耳，時當然也。居尊位而文明，知憂畏如此，故得吉。若自恃其文明之德與所麗中正，泰然不懼，則安能保其吉也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蔡氏淵曰：坎離之用在中，二五皆卦之中也。坎五當位而二不當位，故五為勝；離二當位而五不當位，故二為勝。</p></li><li><p>劉氏定之曰：坎者，陰險之卦，惟剛足以濟之，沈潛剛克也；離者，陽躁之卦，惟柔足以和之，高明柔克也。二五同歸于吉，以柔而然也。</p></li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>惟六二為得明德之正，三之歌嗟，四之突來，則明德昏而性情蕩，忿欲仍而災患至矣。能返之者，其惟哀悔之心乎？五有中德，又適昏極將明之候，故取象如此。三之嗟樂過而悲也，五之嗟自怨自艾也。</p><p>象曰：六五之吉，離王公也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>六五之吉者，所麗得王公之正位也。據在上之勢而明察事理，畏懼憂虞以持之，所以能吉也。不然，豈能安乎？</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><p>趙氏彥肅曰：明極故憂深，憂深故禍弭。又麗於尊位，故致吉也。 蔡氏清曰：味“離王公也”之詞，則知諸卦之五所謂尊位者，不必皆謂天王。凡諸侯之各君其國者，亦足當五也。</p><p>上九：王用出徵，有嘉折首，獲匪其醜，無咎。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>剛明及遠，威震而刑不濫，無咎之道也，故其象佔如此。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>九以陽居上，在離之終，剛明之極者也。明則能照，剛則能斷。能照足以察邪惡，能斷足以行威刑。故王者宜用如是剛明以辨天下之邪惡而行其征伐，則有嘉美之功也。征伐用刑之大者，夫明極則無微不照，斷極則無所寛宥。不約之以中，則傷於嚴察矣。去天下之惡若盡，究其漸染詿誤，則何可勝誅？所傷殘亦甚矣。故但當拆取其魁首，所執獲者非其醜類，則無殘暴之咎也。《書》曰：“殲厥渠魁，脅從罔治。”</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>上九承四五之後，有重明之象。故在人心，則為克己而盡其根株；在國家，則為除亂而去其元惡。《詩》雲：“如火烈烈，則莫我敢遏。苞有三櫱，莫遂莫達。”此爻之義也。</p><p>象曰：王用出徵，以正邦也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>王者用此上九之徳，明照而剛斷，以察除天下之惡，所以正治其邦國。剛明居上之道也。</p>',113)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
